export default `@charset "UTF-8";:root{--color-navy: #0A1628;--color-navy-light: #112240;--color-blue: #0066CC;--color-blue-hover: #0052A3;--color-teal: #00A3A3;--color-purple: #5B21B6;--color-orange: #D97706;--color-green: #059669;--color-red: #DC2626;--color-bg: #F8FAFC;--color-surface: #FFFFFF;--color-border: #E2E8F0;--color-text-primary: #0F172A;--color-text-secondary: #64748B;--color-text-muted: #94A3B8;--sidebar-width: 240px;--topbar-height: 60px;--radius-sm: 6px;--radius-md: 10px;--radius-lg: 16px;--shadow-sm: 0 1px 3px rgba(0,0,0,.08);--shadow-md: 0 4px 12px rgba(0,0,0,.1);--shadow-lg: 0 8px 32px rgba(0,0,0,.14);--transition: .18s ease}*,*:before,*:after{box-sizing:border-box;margin:0;padding:0}html,body{height:100%;font-family:Inter,-apple-system,BlinkMacSystemFont,Segoe UI,sans-serif;font-size:14px;color:var(--color-text-primary);background:var(--color-bg);-webkit-font-smoothing:antialiased}app-root{display:block;height:100%}::-webkit-scrollbar{width:6px;height:6px}::-webkit-scrollbar-track{background:transparent}::-webkit-scrollbar-thumb{background:var(--color-border);border-radius:3px}.btn{display:inline-flex;align-items:center;gap:6px;padding:8px 16px;border-radius:var(--radius-sm);font-size:13px;font-weight:500;cursor:pointer;border:none;transition:var(--transition);text-decoration:none}.btn-primary{background:var(--color-teal);color:#fff}.btn-primary:hover{background:teal}.btn-secondary{background:var(--color-surface);color:var(--color-text-primary);border:1px solid var(--color-border)}.btn-secondary:hover{background:var(--color-bg)}.btn-danger{background:var(--color-red);color:#fff}.btn-sm{padding:5px 10px;font-size:12px}.btn-icon{padding:6px;border-radius:var(--radius-sm);background:transparent;border:none;cursor:pointer;color:var(--color-text-secondary)}.btn-icon:hover{background:var(--color-bg)}.form-group{display:flex;flex-direction:column;gap:4px}.form-label{font-size:12px;font-weight:500;color:var(--color-text-secondary)}.form-control{padding:8px 12px;border:1px solid var(--color-border);border-radius:var(--radius-sm);font-size:13px;color:var(--color-text-primary);background:var(--color-surface);transition:var(--transition);width:100%}.form-control:focus{outline:none;border-color:var(--color-teal);box-shadow:0 0 0 3px #00a3a31f}select.form-control{cursor:pointer}.card{background:var(--color-surface);border-radius:var(--radius-md);border:1px solid var(--color-border);padding:20px;box-shadow:var(--shadow-sm)}.card-header{display:flex;align-items:center;justify-content:space-between;margin-bottom:16px}.card-header h3{font-size:14px;font-weight:600}.badge{display:inline-flex;align-items:center;padding:2px 8px;border-radius:20px;font-size:11px;font-weight:500}.badge-blue{background:#eff6ff;color:#1d4ed8}.badge-green{background:#f0fdf4;color:#15803d}.badge-orange{background:#fef3c7;color:#b45309}.badge-red{background:#fef2f2;color:#b91c1c}.badge-purple{background:#f5f3ff;color:#6d28d9}.badge-gray{background:#f1f5f9;color:#475569}.badge-teal{background:#f0fdfa;color:#0f766e}.table-wrapper{overflow-x:auto}table{width:100%;border-collapse:collapse}table th{padding:10px 12px;text-align:left;font-size:11px;font-weight:600;color:var(--color-text-secondary);text-transform:uppercase;letter-spacing:.5px;border-bottom:1px solid var(--color-border);background:var(--color-bg)}table td{padding:12px;border-bottom:1px solid var(--color-border);font-size:13px}table tr:hover td{background:#f8fafc}table tr:last-child td{border-bottom:none}.stat-grid{display:grid;gap:16px;margin-bottom:20px}.stat-card{background:var(--color-surface);border-radius:var(--radius-md);border:1px solid var(--color-border);padding:16px 20px}.stat-card .stat-label{font-size:11px;font-weight:500;color:var(--color-text-secondary);text-transform:uppercase;letter-spacing:.5px;margin-bottom:6px}.stat-card .stat-value{font-size:24px;font-weight:700}.stat-card .stat-sub{font-size:11px;color:var(--color-text-muted);margin-top:2px}.page-header{display:flex;align-items:center;justify-content:space-between;margin-bottom:20px}.page-header h1{font-size:20px;font-weight:700}.page-header p{font-size:13px;color:var(--color-text-secondary);margin-top:2px}.tabs{display:flex;gap:4px;margin-bottom:16px}.tabs .tab{padding:6px 14px;border-radius:var(--radius-sm);font-size:13px;font-weight:500;cursor:pointer;border:none;background:transparent;color:var(--color-text-secondary);transition:var(--transition)}.tabs .tab.active{background:var(--color-teal);color:#fff}.tabs .tab:hover:not(.active){background:var(--color-bg)}.progress-bar-wrap{height:8px;background:var(--color-border);border-radius:4px;overflow:hidden}.progress-bar{height:100%;border-radius:4px;transition:width .3s ease}.flex{display:flex}.items-center{align-items:center}.justify-between{justify-content:space-between}.gap-2{gap:8px}.gap-3{gap:12px}.mt-2{margin-top:8px}.mb-3{margin-bottom:12px}.font-semibold{font-weight:600}.text-muted{color:var(--color-text-muted)}.text-secondary{color:var(--color-text-secondary)}.grid-2{display:grid;grid-template-columns:1fr 1fr;gap:16px}
`;